<script lang="ts">import{onMount}from'svelte';import{csrfHeaders,idempotencyKey}from'$lib/api/client';import{productLabel}from'$lib/product-language';let orgID='',profile:any={},permissions:any={},provider='',reference='',bank='',name='',last4='',message='',busy=false;async function load(){const r=await fetch('/api/v1/organizations',{credentials:'include'});const d=await r.json();orgID=d.organizations?.[0]?.id??'';if(!orgID)return;const q=await fetch(`/api/v1/organizations/${orgID}/onboarding`,{credentials:'include'});const x=await q.json();profile=x.profile??{};permissions=x.permissions??{};provider=profile.settlement_provider??'';bank=profile.settlement_bank_name??'';name=profile.settlement_account_name??'';last4=profile.settlement_account_last4??''}async function save(){busy=true;const r=await fetch(`/api/v1/organizations/${orgID}/onboarding/settlement`,{method:'PUT',credentials:'include',headers:{'Content-Type':'application/json','Idempotency-Key':idempotencyKey(),...csrfHeaders()},body:JSON.stringify({expected_version:profile.version,provider,provider_reference:reference,bank_name:bank,account_name:name,account_last4:last4})});const d=await r.json().catch(()=>({}));busy=false;message=r.ok?'Your bank account was saved. We are checking it now.':d.detail??'We could not save this bank account.';if(r.ok)profile=d.profile}onMount(load);</script>
<svelte:head><title>Bank account — Kredit</title></svelte:head><main class="shell workspace form-page"><p class="eyebrow">Settings / Bank account</p><h1>Where should we send your money?</h1><p class="lede">Add the business bank account that should receive customer payments. We show only the last four digits after saving it.</p>{#if message}<p class="notice">{message}</p>{/if}<section class="card"><header><h2>Your bank account</h2><span>{productLabel(profile.settlement_state,'Not started')}</span></header>{#if profile.settlement_account_last4}<p class="masked">{profile.settlement_bank_name} · {profile.settlement_account_name} · •••• {profile.settlement_account_last4}</p>{/if}{#if permissions.settlement}<label>Payment company<select bind:value={provider}><option value="">Choose one</option><option value="paystack">Paystack</option><option value="flutterwave">Flutterwave</option><option value="mock-settlement">Testing only</option></select></label><label>Setup number from the payment company<input bind:value={reference} autocomplete="off" /></label><label>Bank name<input bind:value={bank} /></label><label>Name on the account<input bind:value={name} /></label><label>Last four account digits<input bind:value={last4} maxlength="4" inputmode="numeric" /></label><button disabled={busy||!provider||!reference||last4.length!==4} onclick={save}>{busy?'Saving…':'Save this bank account'}</button>{:else}<p>You can see this bank account, but only the owner or a person allowed to handle money can change it.</p>{/if}</section><a href="/app/settings">← All settings</a></main>
<style>.form-page{max-width:52rem}.form-page h1{font-size:clamp(2.4rem,6vw,4.5rem);line-height:1}.card{display:grid;gap:.8rem;padding:1.4rem;border:1px solid var(--color-border);border-radius:1rem;background:var(--color-surface)}header{display:flex;justify-content:space-between;gap:1rem}header span{text-transform:capitalize}.card label{display:grid;gap:.3rem;font-weight:700}.card input,.card select,.card button{padding:.75rem;border:1px solid var(--color-border);border-radius:.65rem;font:inherit}.card button{background:var(--color-primary);color:white;font-weight:800}.masked{font-size:1.15rem}.notice{padding:1rem;background:#eef5ff;border-radius:.7rem}</style>
